definition.raw:
we define formally the local densities of $\sigma_\beta$ and $\gamma_\beta$ by
\begin{equation} \label{defn}
n_{\sigma_\beta}= \sum_{j \in \Nm} \lambda_j | \chi_t  \Lambda_\beta \psi_j |^2, \qquad n_{\gamma_\beta}= \sum_{j \in \Nm} \mu_j | \chi_t  \Lambda_\beta \phi_j|^2.

theorem.raw:
\label{th1}
Let $n_{\sigma_\beta}$ and $n_{\gamma_\beta}$ be the local densities defined formally in \fref{defn} with $u_0 \in \mathcal J_p$ and $\varrho \in L^1(\Rm,\mathcal J_p)$ for $p \in [1,\frac{2d}{2d-1})$. Then, $n_{\sigma_\beta}$ and $n_{\gamma_\beta}$ belong to $L^{r/2}(\Rm^{d+1})$, and we have the estimates
\begin{equation} \label{estnth}
\|n_{\sigma_\beta}\|_{L^{r/2}(\Rm^{d+1})} \leq C_\chi \|u_0\|_{\mathcal J_p}, \qquad \|n_{\gamma_\beta}\|_{L^{r/2}(\Rm^{d+1})} \leq C_\chi \|\varrho\|_{L^1(\Rm,\mathcal J_p)},
\end{equation}
for $r \in [2,\infty)$ and  $\beta >0$ such that 
$$
\left\{
\begin{array}{l} \displaystyle
\displaystyle \beta < \frac{1+d}{r}-\frac{d}{2}, \qquad \textrm{if} \qquad p=1 \qquad \textrm{and} \qquad r>2\\[2mm]
\displaystyle \beta \leq \frac{1}{2}, \qquad \textrm{if} \qquad p=1 \qquad \textrm{and} \qquad r=2\\[2mm]
\displaystyle \beta < \frac{1+d}{r}-\frac{d}{2}-\frac{d}{p'}, \qquad \textrm{if} \qquad  p>1.
\end{array}
\right.
$$
Moreover, under the same conditions as above with $r=2$, we have the following estimates on the operators $\sigma_\beta$ and $\gamma_\beta$ defined in \fref{defop}:
\begin{equation} \label{esttraceth}

\|\sigma_\beta\|_{L^1(\Rm,\mathcal J_1)} \leq C_\chi \|u_0\|_{\mathcal J_p}, \qquad \|\gamma_\beta\|_{L^1(\Rm,\mathcal J_1)} \leq C_\chi \|\varrho\|_{L^1(\Rm,\mathcal J_p)}.


\end{equation}
The constant $C_\chi$ in \fref{estnth}-\fref{esttraceth} depends on $\chi$ but not on $u_0$ and $\varrho$.

lemma.raw:
\label{pr1} Let $\phi_t \equiv \phi(t,x) \in \mathcal S(\Rm^{d+1})$ and $\chi_t \equiv \chi(t,x) \in C_0^\infty(\Rm^{d+1})$. Then,  we have the following estimate:
$$
\left\| (|x|^\alpha+1) \Lambda_{\alpha+\beta} \int_{\Rm } dt \, e^{-i t \Delta} \left(\chi_t \phi_t\right) \right\|_{L^2(\Rm^d)} \leq C_\chi \| \phi_t \|_{L^{r'}(\Rm^{d+1})},
$$
for $\alpha \in (0,\frac{1}{4}]$, $\beta \geq 0$, and $ r \in [2,\infty)$, such that 
\begin{equation} \label{conslem}
\left\{\begin{array}{l}
\displaystyle 2\alpha+\beta < \frac{(d+1)}{r}-\frac{d}{2}, \qquad \textrm{if} \qquad r\in (2,\infty),\\
\displaystyle 2\alpha+\beta \leq \frac{1}{2}, \qquad \textrm{if} \qquad r =2.
\end{array}
\right.
\end{equation}
Moreover, the constant $C_\chi$ above depends on $\chi$ but not on $\phi$.

