\begin{eqnarray*}
\textrm{Tr} \, \big(  e^{-i s \Delta} \varrho(s) e^{is \Delta} F_\beta(s) \big)&=&\textrm{Tr} \, \left( J_\alpha J_\alpha^{-1} e^{-i s \Delta} \varrho(s) e^{is \Delta} (J_\alpha^*)^{-1}J_\alpha^*  F_\beta(s) \right):=II(s).
\end{eqnarray*}

