&=&c_{d,\alpha} \int_{\Rm^d} \frac{(1- e^{i\frac{|x|^2-|y|^2}{4t}}) t^\alpha u_t(y)}{|x-y|^{d+\alpha}} dy\\[3mm]
&:=&R_{t,0}.
\end{eqnarray*}

Then,
\begin{eqnarray*}
(1+|x|) R_{t,0}
&=&c_{d,\alpha} \int_{\Rm^d} (1+|y|)\frac{(1- e^{i\frac{|x|^2-|y|^2}{4t}}) t^\alpha u_t(y)}{|x-y|^{d+\alpha}} dy\\
&&+c_{d,\alpha} \int_{\Rm^d} (|x|-|y|)\frac{(1- e^{i\frac{|x|^2-|y|^2}{4t}}) t^\alpha u_t(y)}{|x-y|^{d+\alpha}} dy\\
&:=&R_{t,1}+R_{t,2}.
\end{eqnarray*}

and as a consequence of Theorem \ref{thCS},
\begin{equation} \label{estJ2}
\| J_2\|_{L^2(\Rm^d)} \leq C \|R_{t,1}+R_{t,2}\|_{L^{q'}(\Rm^{d+1})},\; \textrm{with} \; \left\{
\begin{array}{l}
\displaystyle \alpha+\beta < \frac{(d+1)}{q}-\frac{d}{2}, \quad q'\in [1,2).\\
\displaystyle \alpha+\beta \leq \frac{1}{2}, \quad q'=2.
\end{array}
\right.
\end{equation}
